-- Model logiczny / odczytowy; uruchamiaj w pustej bazie demonstracyjnej.
-- Nie zastępuje migracji aplikacji. Brak wiersza faktu opcjonalnego oznacza NULL.
-- UNIQUE alternatywne, CHECK i reguły między relacjami: model-catalog.json.
-- Przed udostępnieniem zapisu w takim wariancie trzeba egzekwować te ograniczenia
-- na zrekonstruowanych relacjach; sam rozkład nie zachowuje ich lokalnie.
CREATE SCHEMA nf6_reference;
CREATE TABLE nf6_reference."admissions_academicaverage__anchor" (entity_id bigint PRIMARY KEY);
CREATE TABLE nf6_reference."admissions_academicaverage__value" (entity_id bigint PRIMARY KEY REFERENCES nf6_reference."admissions_academicaverage__anchor"(entity_id), value numeric(4,2) NOT NULL);
