CREATE VIEW nf6_reference."admissions_application__reconstructed" AS SELECT a.entity_id AS "id", f1.value AS "public_id", f2.value AS "status", f3.value AS "created_at", f4.value AS "submitted_at", f5.value AS "revision", f6.value AS "input_snapshot", f7.value AS "feedback", f8.value AS "bonus_claimed", f9.value AS "bonus_approved", f10.value AS "portfolio_grade", f11.value AS "payment_approved", f12.value AS "payment_amount", f13.value AS "portfolio_url", f14.value AS "candidate_id", f15.value AS "reviewed_by_id", f16.value AS "offer_id", f17.value AS "round_id", f18.value AS "bonus_category", f19.value AS "bonus_points", f20.value AS "student_number", f21.value AS "sworn_at", f22.value AS "oath_photo_id" FROM nf6_reference."admissions_application__anchor" a LEFT JOIN nf6_reference."admissions_application__public_id" f1 ON f1.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_application__status" f2 ON f2.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_application__created_at" f3 ON f3.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_application__submitted_at" f4 ON f4.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_application__revision" f5 ON f5.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_application__input_snapshot" f6 ON f6.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_application__feedback" f7 ON f7.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_application__bonus_claimed" f8 ON f8.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_application__bonus_approved" f9 ON f9.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_application__portfolio_grade" f10 ON f10.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_application__payment_approved" f11 ON f11.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_application__payment_amount" f12 ON f12.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_application__portfolio_url" f13 ON f13.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_application__candidate_id" f14 ON f14.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_application__reviewed_by_id" f15 ON f15.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_application__offer_id" f16 ON f16.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_application__round_id" f17 ON f17.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_application__bonus_category" f18 ON f18.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_application__bonus_points" f19 ON f19.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_application__student_number" f20 ON f20.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_application__sworn_at" f21 ON f21.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_application__oath_photo_id" f22 ON f22.entity_id=a.entity_id;
