CREATE VIEW nf6_reference."admissions_document__reconstructed" AS SELECT a.entity_id AS "id", f1.value AS "kind", f2.value AS "revision", f3.value AS "file", f4.value AS "original_name", f5.value AS "sha256", f6.value AS "uploaded_at", f7.value AS "application_id", f8.value AS "reused_from_id", f9.value AS "profile_source_id" FROM nf6_reference."admissions_document__anchor" a LEFT JOIN nf6_reference."admissions_document__kind" f1 ON f1.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_document__revision" f2 ON f2.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_document__file" f3 ON f3.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_document__original_name" f4 ON f4.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_document__sha256" f5 ON f5.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_document__uploaded_at" f6 ON f6.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_document__application_id" f7 ON f7.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_document__reused_from_id" f8 ON f8.entity_id=a.entity_id LEFT JOIN nf6_reference."admissions_document__profile_source_id" f9 ON f9.entity_id=a.entity_id;
